export function syncViewport(){const viewport=window.visualViewport;function update(){document.documentElement.style.setProperty('--app-height',(viewport?.height||window.innerHeight)+'px');document.documentElement.style.setProperty('--app-top',(viewport?.offsetTop||0)+'px');}window.addEventListener('resize',update);viewport?.addEventListener('resize',update);viewport?.addEventListener('scroll',update);update();}
